look.customCSS:
/* ───── 方格手稿 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(ellipse at 20% 30%,rgba(255,255,255,.6),transparent 60%),linear-gradient(180deg,#D9D8D4,#E4E2DE) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一块方角面板，返回键后一道竖线分隔 */
[data-wk="chathead"]{background:transparent !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;padding-left:24px !important;padding-right:24px !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:12px !important;right:12px !important;top:calc(var(--app-safe-top, 0px) + 4px) !important;bottom:4px !important;background:#F6F5F2 !important;border:1px solid #C9C7C1 !important;border-radius:2px !important;box-shadow:0 3px 10px rgba(0,0,0,.08) !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="chatback"]{position:relative !important;padding-right:12px !important}
[data-wk="chatback"]::after{content:"" !important;position:absolute !important;right:0 !important;top:15% !important;bottom:15% !important;width:1px !important;background:#C9C7C1 !important}
[data-wk="chatback"] svg{stroke:#1E1E1E !important;stroke-width:1.4 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#1E1E1E !important;font-family:'Times New Roman','Songti SC',serif !important;font-weight:500 !important}
[data-wk="headdim"]{color:#8A8984 !important;letter-spacing:.1em !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"] *,[data-wk="chathead"] img{border-radius:1px !important;box-shadow:0 0 0 1px #C9C7C1 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgMTEgTDEyIDQgTDIwIDExIFYyMCBINFonIGZpbGw9J25vbmUnIHN0cm9rZT0nIzFFMUUxRScgc3Ryb2tlLXdpZHRoPScxLjMnIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/22px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgNyBIMjAgTTQgMTIgSDIwIE00IDE3IEgxNicgc3Ryb2tlPScjMUUxRTFFJyBzdHJva2Utd2lkdGg9JzEuMycvPjwvc3ZnPg==") center/22px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 名字：气泡上方一块浅色小签条，宽字距大写感 */
[data-wk="name"]{display:inline-block !important;background:#F6F5F2 !important;color:#1E1E1E !important;font-family:'Times New Roman','Songti SC',serif !important;font-size:10px !important;letter-spacing:.3em !important;padding:2px 10px !important;margin:0 0 6px !important;border-radius:0 !important}
[data-wk="name"][data-me="1"]{align-self:flex-end !important}

/* 气泡：方角。我的纯黑，他的浅灰细框 */
[data-wk="bubble"][data-kind="text"]{border-radius:2px !important;padding:12px 18px !important;font-size:15px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#1E1E1E !important;color:#fff !important;border:1px solid #1E1E1E !important;box-shadow:0 3px 10px rgba(0,0,0,.15) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#F6F5F2 !important;color:#1E1E1E !important;border:1px solid #C9C7C1 !important;box-shadow:0 3px 10px rgba(0,0,0,.08) !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}

/* 时间：浅色长条，左右两道细线 */
[data-wk="time"] > span{display:inline-block !important;background:#F6F5F2 !important;color:#1E1E1E !important;border:none !important;border-radius:0 !important;padding:4px 18px !important;font-family:'Times New Roman','Songti SC',serif !important;letter-spacing:.3em !important;font-size:11px !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;display:inline-block !important;width:40px !important;height:1px !important;background:#1E1E1E !important;vertical-align:middle !important;margin:0 8px !important}
/* 已读：一道短横线＋小字 */
[data-wk="meta"]{display:inline-flex !important;align-items:center !important;background:#F6F5F2 !important;color:#8A8984 !important;border-radius:0 !important;padding:1px 8px !important;font-size:10px !important;letter-spacing:.2em !important}
[data-wk="meta"]::before{content:"" !important;width:12px !important;height:1px !important;background:#8A8984 !important;margin-right:6px !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#F6F5F2 !important;border:1px solid #C9C7C1 !important;border-radius:2px !important}
[data-wk="typingdot"]{background:#1E1E1E !important;border-radius:0 !important;width:4px !important;height:4px !important}
[data-wk="narrink"]{background:#F6F5F2 !important;border-radius:0 !important;color:#1E1E1E !important;padding:3px 10px !important}
[data-wk="sysnotetext"]{color:#8A8984 !important;letter-spacing:.1em !important}

/* 底栏：方角面板包住加号｜输入｜对话气泡；外面一块黑色方形发送键 */
[data-wk="composer"]{background:transparent !important;border-top:none !important;position:relative !important;z-index:2 !important;align-items:center !important;padding-left:22px !important;padding-right:14px !important;gap:8px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10px !important;right:68px !important;top:8px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) + 0px) !important;background:#F6F5F2 !important;border:1px solid #C9C7C1 !important;border-radius:2px !important;box-shadow:0 3px 10px rgba(0,0,0,.08) !important;pointer-events:none !important;z-index:-1 !important}
[data-wk="chatinput"]{background:transparent !important;border:none !important;border-left:1px solid #C9C7C1 !important;border-radius:0 !important;box-shadow:none !important;color:#1E1E1E !important;padding-left:14px !important;letter-spacing:.1em !important}
[data-wk="chatinput"]::placeholder{color:#8A8984 !important}
[data-wk="chatplus"],[data-wk="chatreply"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDUgVjE5IE01IDEyIEgxOScgc3Ryb2tlPScjMUUxRTFFJyBzdHJva2Utd2lkdGg9JzEuNCcgc3Ryb2tlLWxpbmVjYXA9J3NxdWFyZScvPjwvc3ZnPg==") center/20px no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyOCAyNCc+PHBhdGggZD0nTTMgMyBIMjUgVjE3IEgxMiBMNiAyMiBWMTcgSDNaJyBmaWxsPSdub25lJyBzdHJva2U9JyMxRTFFMUUnIHN0cm9rZS13aWR0aD0nMS4zJyBzdHJva2UtbGluZWpvaW49J3JvdW5kJy8+PC9zdmc+") center/24px no-repeat !important;margin-right:16px !important}
[data-wk="send"]{order:99 !important;width:46px !important;min-width:46px !important;height:46px !important;border:1px solid #1E1E1E !important;border-radius:2px !important;background:#1E1E1E url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDIwIFY1IE02IDExIEwxMiA1IEwxOCAxMScgZmlsbD0nbm9uZScgc3Ryb2tlPScjZmZmJyBzdHJva2Utd2lkdGg9JzEuNCcvPjwvc3ZnPg==") center/22px no-repeat !important;box-shadow:0 3px 10px rgba(0,0,0,.2) !important;opacity:1 !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="msg"][data-first="0"] [data-wk="name"]{display:none !important}
[data-wk="msg"][data-first="0"]{margin-top:-4px !important}
[data-wk="composer"]::before{top:6px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) + 6px) !important}
[data-wk="send"]{height:44px !important;width:44px !important;min-width:44px !important}


/* 顶栏名字露全：图标缩小、名字区撑满、名字旁小箭头藏掉 */
[data-wk="chathead"]{gap:6px !important;padding-right:18px !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="chathead"] [data-wk="headname"] [data-wk="headdim"] svg,[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;background-size:20px !important}
[data-wk="chatback"]{padding-right:8px !important}
/* 底栏面板包住整条输入框 */
[data-wk="composer"]::before{top:4px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) - 8px) !important}
[data-wk="chatinput"]{min-height:38px !important;align-self:center !important}
[data-wk="stlink"]{display:none !important}

/* ───── 方格手稿 · 第二批：卡片（形状不动，方角细线面板；小巧思：左上角一行宽字距小标题，像稿纸栏目） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="rpcard"]{background:#F6F5F2 !important;border:1px solid #C9C7C1 !important;border-radius:2px !important;box-shadow:0 3px 10px rgba(0,0,0,.08) !important;position:relative !important;color:#1E1E1E !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#1E1E1E !important;border-color:#C9C7C1 !important}
[data-wk="transfercard"],[data-wk="namecard"],[data-part="offlog"]{padding-top:28px !important}
[data-wk="transfercard"]::before,[data-wk="namecard"]::before,[data-part="offlog"]::before{position:absolute !important;left:14px !important;top:9px !important;font:10px/1 'Times New Roman','Songti SC',serif !important;letter-spacing:.35em !important;color:#8A8984 !important;padding-bottom:4px !important;border-bottom:1px solid #C9C7C1 !important}
[data-wk="transfercard"]::before{content:"TRANSFER · 转账" !important}
[data-wk="namecard"]::before{content:"CARD · 名片" !important}
[data-part="offlog"]::before{content:"NOTE · 线下" !important}
[data-wk="transferamount"],[data-wk="transfercur"]{font-family:'Times New Roman','Songti SC',serif !important;font-weight:400 !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:#1E1E1E !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:transparent !important;border-top:1px solid #C9C7C1 !important;letter-spacing:.2em !important}
[data-wk="transferbtn"]{border-radius:2px !important}
[data-wk="transferbtn"][data-part="take"]{background:#1E1E1E !important;color:#fff !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;color:#1E1E1E !important;border:1px solid #1E1E1E !important}
[data-wk="transferseal"]{border:1px solid #1E1E1E !important;border-radius:2px !important;color:#1E1E1E !important;background:transparent !important;box-shadow:none !important;transform:rotate(-6deg) !important;font-family:'Times New Roman','Songti SC',serif !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：留红，只改成方角细线 */
[data-wk="rpcard"]{background:linear-gradient(160deg,#C0453A,#9E3029) !important;border-color:#8A2A22 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpenvelope"]{border-radius:4px !important}
/* 照片：白边像贴在稿纸上，四角一点胶痕 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:0 !important;background:#E2E0DB !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#1E1E1E !important}
/* 语音：方角，我黑他浅 */
[data-wk="voice"][data-me]{background:#F6F5F2 !important;border:1px solid #C9C7C1 !important;border-radius:2px !important;box-shadow:0 3px 10px rgba(0,0,0,.08) !important}
[data-wk="voice"][data-me="1"]{background:#1E1E1E !important;border-color:#1E1E1E !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#1E1E1E !important}
[data-wk="voice"][data-me="1"] > *{color:#fff !important}
[data-wk="voicewave"] span{background:#1E1E1E !important;border-radius:0 !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#fff !important}
[data-wk="wxcardsky"]{background:#ECEAE5 !important}
[data-wk="wxcardsky"] *{color:#1E1E1E !important}
[data-wk="wxcardsky"] svg{stroke:#1E1E1E !important}
[data-wk="wxcardsay"]{background:#F6F5F2 !important;border-top:1px solid #C9C7C1 !important;color:#1E1E1E !important}
[data-wk="geopin"]{background:#1E1E1E !important;border-radius:0 !important;box-shadow:none !important}
[data-wk="geopinstem"]{background:#1E1E1E !important}
[data-wk="namecard"] img{border-radius:1px !important;box-shadow:0 0 0 1px #C9C7C1 !important}
/* 拍一拍、通话结束、系统提示：浅色长条 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:#F6F5F2 !important;color:#1E1E1E !important;border:none !important;border-radius:0 !important;padding:3px 14px !important;letter-spacing:.15em !important}
[data-wk="note"][data-part="call"] svg{stroke:#1E1E1E !important}
[data-wk="note"][data-part="callsum"]{color:#8A8984 !important}
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{display:inline-block !important;background:#F6F5F2 !important;color:#8A8984 !important;padding:3px 14px !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#8A8984 !important;letter-spacing:.15em !important}
[data-wk="offlogtranscript"]{border-top:1px solid #C9C7C1 !important}
/* 加号面板：方格，一格一个 */
[data-wk="chatpanel"]{background:#F6F5F2 !important;border-top:1px solid #C9C7C1 !important}
[data-wk="chattoolicon"]{background:transparent !important;border:1px solid #C9C7C1 !important;border-radius:2px !important;box-shadow:none !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#1E1E1E !important;color:#1E1E1E !important}
[data-wk="chattoollabel"]{color:#1E1E1E !important;letter-spacing:.15em !important}
/* 引用三处：左一道黑竖线，方角 */
[data-wk="quotedraft"]{background:transparent !important;border-top:none !important}
[data-wk="quote"]{background:#F6F5F2 !important;color:#1E1E1E !important;border:none !important;border-left:2px solid #1E1E1E !important;border-radius:0 !important;opacity:1 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#1E1E1E !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.6 !important}

[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]{display:none !important}
[data-wk="msg"][data-last="1"] [data-wk="meta"] [data-wk="stlink"]{display:none !important}
